SELECT sm.*, kp.name as kp_name, kp.branch as branch
FROM student_mastery sm
LEFT JOIN knowledge_point kp ON sm.kp_id = kp.id
WHERE sm.student_id = #{studentId}
ORDER BY sm.mastery_score ASC
LIMIT #{limit}

SELECT sm.*, kp.name as kp_name, kp.branch as branch
FROM student_mastery sm
LEFT JOIN knowledge_point kp ON sm.kp_id = kp.id
WHERE sm.student_id = #{studentId}
ORDER BY sm.mastery_score DESC
LIMIT #{limit}

mapper.update:
UPDATE student_mastery 
SET mastery_score = #{masteryScore}, update_time = NOW()
WHERE student_id = #{studentId} AND kp_id = #{kpId}
